def districts():
    """Kreise by Land, coded as the record has them: Land and Kreis."""
    return [(state, [(code, name) for code, name in DISTRICTS if code[:2] == key]) for key, state in STATES]


def places():
    """Where someone lives or gained the HZB: a Kreis, or 99 and the state abroad."""
    return districts() + [('Ausland', [('99' + code, name) for code, name in FOREIGN])]


def countries():
    return COUNTRIES


def german():
    return UNIVERSITIES


def universities():
    """Where someone studied: a German Hochschule, or 9990 and the state abroad."""
    return [('In Deutschland', UNIVERSITIES), ('Im Ausland', [(ABROAD + code, name) for code, name in FOREIGN])]


def fields():
    return FIELDS


def degrees():
    return DEGREES


def kind(degree):
    """The usual Studienart of an Abschluss: a Master follows a first degree, a Promotion any degree."""
    name = dict(DEGREES).get(degree, '')
    return '9' if degree == '97' else '7' if 'Master' in name else '5' if name.startswith('Promotion (') or degree in ('91', '92') else '1'


def grade(average, honours=False):
    """Gesamtnote of a passed Abschlussprüfung."""
    if average is None:
        return '8'
    return '0' if honours else '1' if average <= 1.5 else '2' if average <= 2.5 else '3' if average <= 3.5 else '4'


def guest(field):
    """Fachrichtung (14) of a course in a Studienfach, for the Gasthörer: Musik, Musikwissenschaft/-pädagogik, or general."""
    return '83' if field in MUSIC else '85' if field in ('113', '114') else '98'
